@EventBusSubscriber(modid="vandorlabs",value=Dist.CLIENT)
public final class NativeScreenJournalRenderChecks {
 private static final class Gallery extends net.minecraft.client.gui.screens.Screen {Gallery(){super(net.minecraft.network.chat.Component.literal("Journal canvas fixture"));}@Override public void render(net.minecraft.client.gui.GuiGraphics gui,int x,int y,float tick){}}
 private static final class Discard implements VertexConsumer {public VertexConsumer addVertex(float x,float y,float z){return this;}public VertexConsumer setColor(int r,int g,int b,int a){return this;}public VertexConsumer setUv(float u,float v){return this;}public VertexConsumer setUv1(int u,int v){return this;}public VertexConsumer setUv2(int u,int v){return this;}public VertexConsumer setNormal(float x,float y,float z){return this;}}
 private static final Matrix4f IDENTITY=new Matrix4f();private static final ScreenSurface.Quad CONTENT=ScreenSurface.quad(ScreenSurface.Kind.FLAT,false);
 private static NativeScreenJournalRenderer renderer;private static NativeScreenChipView[] scenes;private static boolean capture,done;private static int frames,generation;
 private static void need(boolean yes,String why){if(!yes)throw new AssertionError("Native journal: "+why);}
 private static NativeScreenChipView projection(JsonObject row){int variant=row.get("variant").getAsInt();var tag=new CompoundTag();tag.putInt("Company",row.get("company").getAsInt());tag.putInt("Logo",0);tag.putBoolean("Icon",row.get("occupied").getAsBoolean());tag.putBoolean("Occupied",row.get("occupied").getAsBoolean());tag.putInt("Output",row.get("occupied").getAsBoolean()?15:0);tag.putLong("Sequence",0);tag.putInt("Age",20);tag.putInt("RejectedFor",0);tag.putLong("RejectedUntil",0);tag.putInt("Page",row.get("page").getAsInt());tag.putBoolean("Master",row.get("master").getAsBoolean());if(variant==2)tag.putString("DisplayName",row.get("displayName").getAsString());if(variant>=9){var journal=new CompoundTag();journal.putString("ChipType","journal");journal.putString("JournalTitle",variant==9?"":variant==10?"W".repeat(40):"MULTIPAGE");var pages=new ListTag();pages.add(StringTag.valueOf(variant==9?"First line\nSecond line":variant==10?"W".repeat(512):"\n".repeat(512)));pages.add(StringTag.valueOf("A second entry"));for(int i=2;i<8;i++)pages.add(StringTag.valueOf(""));journal.put("JournalPages",pages);tag.put("Journal",journal);}return NativeScreenChipView.read(tag);}
 private static void prepare()throws Exception{var mc=Minecraft.getInstance();renderer=new NativeScreenJournalRenderer(mc.font,NativePanelPlaybackRenderer.currentBake());scenes=new NativeScreenChipView[12];JsonArray profiles;try(var input=new java.util.zip.GZIPInputStream(java.nio.file.Files.newInputStream(java.nio.file.Path.of(System.getProperty("vandorlabs.journalOverlayReference"))))){profiles=JsonParser.parseReader(new java.io.InputStreamReader(input,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject().getAsJsonArray("profiles");}int text=0,logo=0;String stockName=null;for(var element:profiles){var row=element.getAsJsonObject();if(row.get("variant").getAsInt()==1)stockName=row.get("displayName").getAsString();for(var item:row.getAsJsonArray("text")){var command=item.getAsJsonObject();need(mc.font.width(command.get("text").getAsString())==command.get("width").getAsInt(),"Source font metrics "+command.get("text"));text++;}if(row.get("master").getAsBoolean()){int company=row.get("company").getAsInt(),height=row.get("height").getAsInt();double aspect=renderer.logoAspect(company);need(aspect>0,"authored company logo "+company);double width=Math.min(304,(height-16)*aspect),h=width/aspect,x=(320-width)/2,y=(height-h)/2;var data=row.getAsJsonArray("draws").get(1).getAsJsonObject().getAsJsonArray("data");double[] xs={x,x+width,x+width,x},ys={y+h,y+h,y,y};for(int v=0;v<4;v++){need(Math.abs((float)xs[v]-Float.intBitsToFloat(data.get(v*8).getAsInt()))<.00002,"Source company width");need(Math.abs((float)ys[v]-Float.intBitsToFloat(data.get(v*8+1).getAsInt()))<.00002,"Source company height");}logo++;}if(row.get("height").getAsInt()==320&&row.get("requested").getAsInt()==1)scenes[row.get("variant").getAsInt()]=projection(row);}
  need(text==352&&logo==72,"actual Source command coverage");need(com.vandorlabs.neoforge.credentials.NativeCredentialItems.dataChip(0).getHoverName().getString().equals(stockName),"stock name localized at client against Source="+stockName);var discard=new Discard();net.minecraft.client.renderer.MultiBufferSource buffers=layer->discard;var pose=new PoseStack();for(int i=0;i<30000;i++)renderer.render(scenes[10],CONTENT,IDENTITY,pose,buffers,0xf000f0);long builds=renderer.builds();var bean=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();if(!bean.isThreadAllocatedMemoryEnabled())bean.setThreadAllocatedMemoryEnabled(true);long before=bean.getThreadAllocatedBytes(Thread.currentThread().threadId());for(int i=0;i<10000;i++)renderer.render(scenes[10],CONTENT,IDENTITY,pose,buffers,0xf000f0);long allocated=bean.getThreadAllocatedBytes(Thread.currentThread().threadId())-before;need(allocated<=4096&&renderer.builds()==builds,"warm cache bytes="+allocated+" builds="+renderer.builds());System.out.println("[vandorlabs][screen-journal-render] warm PASS 10000 draws bytes="+allocated+" Source font commands="+text+" logo profiles="+logo+" retained="+renderer.retainedBytes());
  var equivalent=scenes[10].write();equivalent.putLong("Sequence",99);equivalent.putInt("Age",5);long stable=renderer.builds();renderer.render(NativeScreenChipView.read(equivalent),CONTENT,IDENTITY,pose,buffers,0xf000f0);need(renderer.builds()==stable,"equivalent text and reader-only update reuse font geometry");
  for(int i=0;i<1200;i++){var changed=scenes[2].write();changed.putString("DisplayName",i+"-"+"M".repeat(240));renderer.render(NativeScreenChipView.read(changed),CONTENT,IDENTITY,pose,buffers,0xf000f0);}
  need(renderer.retainedBytes()<=4L*1024*1024+512*1024,"weighted journal cache budget");for(int i=0;i<12000;i++)renderer.render(scenes[i%12],CONTENT,IDENTITY,pose,buffers,0xf000f0);stable=renderer.builds();before=bean.getThreadAllocatedBytes(Thread.currentThread().threadId());for(int i=0;i<12000;i++)renderer.render(scenes[i%12],CONTENT,IDENTITY,pose,buffers,0xf000f0);allocated=bean.getThreadAllocatedBytes(Thread.currentThread().threadId())-before;need(allocated<=4096&&renderer.builds()==stable,"mixed logo/journal/blank warm cache bytes="+allocated);System.out.println("[vandorlabs][screen-journal-render] cache PASS 1200 distinct names retained="+renderer.retainedBytes()+" mixed12000Bytes="+allocated+" equivalent publication reuse");}
 @SubscribeEvent public static void draw(ScreenEvent.Render.Post event)throws Exception{if(done||!"true".equals(System.getenv("VANDOR_SCREEN_JOURNAL_RENDER_CHECK")))return;var mc=Minecraft.getInstance();if(mc.getOverlay()!=null)return;if(event.getScreen() instanceof net.minecraft.client.gui.screens.TitleScreen){mc.setScreen(new Gallery());return;}if(!(event.getScreen() instanceof Gallery))return;if(renderer==null)prepare();var gui=event.getGuiGraphics();gui.fill(0,0,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight(),0xff202830);gui.flush();com.mojang.blaze3d.systems.RenderSystem.clear(org.lwjgl.opengl.GL11.GL_DEPTH_BUFFER_BIT,Minecraft.ON_OSX);var buffers=mc.renderBuffers().bufferSource();if(frames>=4)for(int i=0;i<12;i++){var poses=gui.pose();poses.pushPose();try{poses.translate(8+i%4*155+144,8+i/4*115+104,350);poses.scale(-9,-6.5F,-1);renderer.render(scenes[i],CONTENT,IDENTITY,poses,buffers,0xf000f0);}finally{poses.popPose();}buffers.endBatch();gui.flush();}capture=++frames==4||frames==9;}
 @SubscribeEvent public static void frame(RenderFrameEvent.Post event)throws Exception{if(!capture||done)return;capture=false;var mc=Minecraft.getInstance();try(var image=Screenshot.takeScreenshot(mc.getMainRenderTarget())){double scale=mc.getWindow().getGuiScale();for(int i=0;i<12;i++){int ink=0,details=0,text=0,x0=(int)((8+i%4*155)*scale),y0=(int)((8+i/4*115)*scale);for(int y=0;y<(int)(104*scale);y++)for(int x=0;x<(int)(144*scale);x++){int rgb=image.getPixelRGBA(x+x0,y+y0)&0xffffff;if(rgb!=0x302820)ink++;if(rgb!=0x302820&&rgb!=0&&rgb!=0x302315)details++;if(rgb==0xffeec8||rgb==0xf5ede2||rgb==0xd0bfa6)text++;}need(frames==4?ink==0:details>100,"visible non-background content scene="+i+" details="+details+" ink="+ink);if(frames==9&&(i<3||i>8))need(text>20,"visible journal labels scene="+i+" pixels="+text);}var path=mc.gameDirectory.toPath().resolve("screenshots/screen-journal-"+generation+"-"+(frames==4?"disabled":"positive")+".png");java.nio.file.Files.createDirectories(path.getParent());image.writeToFile(path);if(frames==9){if(generation++==0){renderer.clear();need(renderer.retainedBytes()==0,"retire peak font tables");renderer=null;frames=0;mc.reloadResourcePacks();}else{done=true;System.out.println("[vandorlabs][screen-journal-render] title PASS 12 scenes/6 authored logos/journal and blank labels/negative empty/resource reload; private consumer only");mc.stop();}}}}
}
